17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        if (bindingResult.hasErrors()) {
141	            errors.addAllErrors(bindingResult);
142	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
143	                .map(fieldError -> {
144	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
145	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
146	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
147	                        fieldError.getField(),
148	                        defaultMessage,
149	                        rejectedValue);
150	                    return new ValidationMessageDto(message)
151	                        .putAdditionalProperty("field", fieldError.getField())
152	                        .putAdditionalProperty("rejectedValue", rejectedValue)
153	                        .putAdditionalProperty("defaultMessage", defaultMessage);
154	                })
155	                .toList();
156	            logger.debug("Validation error at {} {}: {}",
157	                request.getMethod(),
158	                request.getRequestURI(),
159	                bindingResult.getFieldErrors());
160	            List<String> errorFields = bindingResult.getFieldErrors().stream()
161	                .map(FieldError::getField)
162	                .distinct()
163	                .toList();
164	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
165	            detail.setProperty("errors", errorFields);
166	            return ResponseEntity.status(status).body(detail);
167	        }
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles {@link InvalidTelephoneException} raised when a request to create an owner supplies a
173	     * telephone that does not normalize to exactly ten digits.
174	     *
175	     * @param e The {@link InvalidTelephoneException} to be handled
176	     * @param request {@link HttpServletRequest} object referring to the current request.
177	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
178	     *         whose {@code errors} array names the {@code telephone} field.
179	     */
180	    @ExceptionHandler(InvalidTelephoneException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
183	        HttpStatus status = HttpStatus.BAD_REQUEST;
184	        logger.debug("Invalid telephone at {} {}: {}",
185	            request.getMethod(),
186	            request.getRequestURI(),
187	            e.getRejectedValue());
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
189	        detail.setProperty("errors", List.of("telephone"));
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidPostcodeException} raised when a request to create an owner supplies a
195	     * {@code postcode} that is out of range for the owner's city region.
196	     *
197	     * @param e The {@link InvalidPostcodeException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
200	     *         whose {@code errors} array names the {@code postcode} field.
201	     */
202	    @ExceptionHandler(InvalidPostcodeException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
205	        HttpStatus status = HttpStatus.BAD_REQUEST;
206	        logger.debug("Invalid postcode at {} {}: {}",
207	            request.getMethod(),
208	            request.getRequestURI(),
209	            e.getRejectedValue());
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
211	        detail.setProperty("errors", List.of("postcode"));
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	    /**
216	     * Handles {@link DisposableEmailDomainException} raised when a request to create an owner supplies
217	     * an {@code email} whose domain is on the disposable-domain blocklist.
218	     *
219	     * @param e The {@link DisposableEmailDomainException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
222	     *         whose {@code errors} array names the {@code email} field.
223	     */
224	    @ExceptionHandler(DisposableEmailDomainException.class)
225	    @ResponseBody
226	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
227	        HttpStatus status = HttpStatus.BAD_REQUEST;
228	        logger.debug("Disposable email domain at {} {}: {}",
229	            request.getMethod(),
230	            request.getRequestURI(),
231	            e.getRejectedValue());
232	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
233	        detail.setProperty("errors", List.of("email"));
234	        return ResponseEntity.status(status).body(detail);
235	    }
236	
237	    /**
238	     * Handles {@link FutureRegistrationDateException} raised when a request to create an owner supplies a
239	     * {@code registrationDate} that is later than the current server date.
240	     *
241	     * @param e The {@link FutureRegistrationDateException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
244	     *         whose {@code errors} array names the {@code registrationDate} field.
245	     */
246	    @ExceptionHandler(FutureRegistrationDateException.class)
247	    @ResponseBody
248	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
249	        HttpStatus status = HttpStatus.BAD_REQUEST;
250	        logger.debug("Future registration date at {} {}: {}",
251	            request.getMethod(),
252	            request.getRequestURI(),
253	            e.getRejectedValue());
254	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
255	        detail.setProperty("errors", List.of("registrationDate"));
256	        return ResponseEntity.status(status).body(detail);
257	    }
258	
259	    /**
260	     * Handles {@link DuplicateIdentityException} raised when a request to create an owner produces an
261	     * identity key ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) whose
262	     * whole value already belongs to another owner. This single check consolidates the former
263	     * separate telephone, email and household duplicate checks.
264	     *
265	     * @param e The {@link DuplicateIdentityException} to be handled
266	     * @param request {@link HttpServletRequest} object referring to the current request.
267	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status,
268	     *         whose {@code errors} array names the {@code identityKey} field.
269	     */
270	    @ExceptionHandler(DuplicateIdentityException.class)
271	    @ResponseBody
272	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
273	        HttpStatus status = HttpStatus.CONFLICT;
274	        logger.debug("Duplicate identity key at {} {}: {}",
275	            request.getMethod(),
276	            request.getRequestURI(),
277	            e.getRejectedValue());
278	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
279	        detail.setProperty("errors", List.of("identityKey"));
280	        return ResponseEntity.status(status).body(detail);
281	    }
282	
283	    /**
284	     * Handles {@link CityAtCapacityException} raised when a request to create an owner names a city
285	     * that already contains 50 or more owners.
286	     *
287	     * @param e The {@link CityAtCapacityException} to be handled
288	     * @param request {@link HttpServletRequest} object referring to the current request.
289	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status,
290	     *         whose {@code errors} array names the {@code city} field.
291	     */
292	    @ExceptionHandler(CityAtCapacityException.class)
293	    @ResponseBody
294	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
295	        HttpStatus status = HttpStatus.CONFLICT;
296	        logger.debug("City at capacity at {} {}: {}",
297	            request.getMethod(),
298	            request.getRequestURI(),
299	            e.getCity());
300	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
301	        detail.setProperty("errors", List.of("city"));
302	        return ResponseEntity.status(status).body(detail);
303	    }
304	
305	    /**
306	     * Handles {@link DailyRegistrationLimitException} raised when a request to create an owner would
307	     * exceed the daily registration limit, i.e. 100 or more owners have already been created today.
308	     *
309	     * @param e The {@link DailyRegistrationLimitException} to be handled
310	     * @param request {@link HttpServletRequest} object referring to the current request.
311	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests
312	     *         status.
313	     */
314	    @ExceptionHandler(DailyRegistrationLimitException.class)
315	    @ResponseBody
316	    public ResponseEntity<ProblemDetail> handleDailyRegistrationLimitException(DailyRegistrationLimitException e, HttpServletRequest request) {
317	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
318	        logger.debug("Daily registration limit reached at {} {}: {}",
319	            request.getMethod(),
320	            request.getRequestURI(),
321	            e.getDate());
322	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
323	        return ResponseEntity.status(status).body(detail);
324	    }
325	
326	    /**
327	     * Handles {@link MissingOwnerFieldsException} raised when a request to create an owner omits or
328	     * blanks out one or more required fields that Bean Validation does not otherwise reject.
329	     *
330	     * @param e The {@link MissingOwnerFieldsException} to be handled
331	     * @param request {@link HttpServletRequest} object referring to the current request.
332	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
333	     *         whose {@code errors} array lists the name of each missing or blank field.
334	     */
335	    @ExceptionHandler(MissingOwnerFieldsException.class)
336	    @ResponseBody
337	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
338	        HttpStatus status = HttpStatus.BAD_REQUEST;
339	        logger.debug("Missing owner fields at {} {}: {}",
340	            request.getMethod(),
341	            request.getRequestURI(),
342	            e.getFields());
343	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
344	        detail.setProperty("errors", e.getFields());
345	        return ResponseEntity.status(status).body(detail);
346	    }
347	
348	}
